def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Edge bars project perpendicular in the color that appears as isolated markers (3).
    # Bars from top/bottom extend down/up only where corresponding columns are blank.
    for c in range(w):
        if grid[0][c]==1:
            for r in range(1,h-1):
